"""Competency model loaders."""

from __future__ import annotations

from abc import ABC, abstractmethod
from pathlib import Path

import yaml

from kompas.core.exceptions import ConfigurationError
from kompas.domain.competency import CompetencyModel


class CompetencyModelLoader(ABC):
    """Source of the competency model (file, database, HR system...)."""

    @abstractmethod
    def load(self) -> CompetencyModel: ...


class YamlCompetencyModelLoader(CompetencyModelLoader):
    """Loads the model generated by ``scripts/import_competency_model.py``."""

    def __init__(self, path: Path) -> None:
        self.path = Path(path)

    def load(self) -> CompetencyModel:
        if not self.path.is_file():
            raise ConfigurationError(
                f"Competency model not found: {self.path}. Run `make import-model` to generate it."
            )
        with self.path.open(encoding="utf-8") as fh:
            data = yaml.safe_load(fh)
        data.pop("summary", None)
        return CompetencyModel.model_validate(data)
